#include <vector>
#include <string>
#include <cmath>
#include <algorithm>

class Solution {
private:
    int digitSpread(int x) {
        std::string s = std::to_string(std::abs(x));
        int mx = 0, mn = 9;
        for (char c : s) {
            mx = std::max(mx, c - '0');
            mn = std::min(mn, c - '0');
        }
        return mx - mn;
    }
public:
    long long sumWithMaxDigitRange(std::vector<int>& nums) {
        int maxSpread = -1;
        for (int x : nums) {
            maxSpread = std::max(maxSpread, digitSpread(x));
        }
        long long sum = 0;
        for (int x : nums) {
            if (digitSpread(x) == maxSpread) sum += x;
        }
        return sum;
    }
};

class Solution {
    private int digitSpread(int x) {
        String s = Integer.toString(Math.abs(x));
        int mx = 0, mn = 9;
        for (char c : s.toCharArray()) {
            mx = Math.max(mx, c - '0');
            mn = Math.min(mn, c - '0');
        }
        return mx - mn;
    }

    public long sumWithMaxDigitRange(int[] nums) {
        int maxSpread = -1;
        for (int x : nums) {
            maxSpread = Math.max(maxSpread, digitSpread(x));
        }
        long sum = 0;
        for (int x : nums) {
            if (digitSpread(x) == maxSpread) sum += x;
        }
        return sum;
    }
}

function digitSpread(x) {
    const s = String(Math.abs(x));
    let mx = 0, mn = 9;
    for (const c of s) {
        const d = Number(c);
        mx = Math.max(mx, d);
        mn = Math.min(mn, d);
    }
    return mx - mn;
}

function sumWithMaxDigitRange(nums) {
    let maxSpread = -1;
    for (const x of nums) {
        maxSpread = Math.max(maxSpread, digitSpread(x));
    }
    let sum = 0;
    for (const x of nums) {
        if (digitSpread(x) === maxSpread) sum += x;
    }
    return sum;
}
